(* charitable sports event meeting (I)-(III) of 7701(b)(5)(A)(iv) *)
type sports_event = {
  organized_for_501c3_benefit : bool; (* (I) organized for primary purpose of benefiting a 501(c)(3), tax-exempt org *)
  all_net_proceeds_contributed : bool; (* (II) all net proceeds contributed to such organization *)
  volunteers_do_substantially_all_work : bool; (* (III) volunteers used for substantially all work performed *)
}

type athlete = {
  is_professional_athlete : bool;
  temporarily_in_united_states : bool;
  event : sports_event option; (* event athlete is competing in, if any *)
}

(* event qualifies under (I), (II), (III) *)
let is_qualifying_sports_event (event : sports_event) : bool =
  event.organized_for_501c3_benefit &&
  event.all_net_proceeds_contributed &&
  event.volunteers_do_substantially_all_work

(* 7701(b)(5)(A)(iv): professional athlete temporarily in US to compete in qualifying charitable sports event *)
let is_exempt_athlete_charitable_event (athlete : athlete) : bool =
  athlete.is_professional_athlete &&
  athlete.temporarily_in_united_states &&
  match athlete.event with
  | Some event -> is_qualifying_sports_event event
  | None -> false
